import { app, page, route, query, action, api } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { FolderPage } from "./src/FolderPage" with { type: "ref" };
import { LogsPage } from "./src/LogsPage" with { type: "ref" };
import { SharePage } from "./src/SharePage" with { type: "ref" };
import { SignupPage } from "./src/SignupPage" with { type: "ref" };
import { LoginPage } from "./src/LoginPage" with { type: "ref" };

import { createFolder, createShareLink } from "./src/actions" with { type: "ref" };
import { getFolderContents, getAccessLogs, getShareLinkInfo } from "./src/queries" with { type: "ref" };
import { downloadFile, uploadFile } from "./src/apis" with { type: "ref" };

export default app({
  name: "app",
  wasp: { version: "^0.25.0" },
  title: "Wasp File Management System",
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {},
    },
    onAuthFailedRedirectTo: "/login",
    onAuthSucceededRedirectTo: "/",
  },
  spec: [
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("FolderRoute", "/folder/:folderId", page(FolderPage, { authRequired: true })),
    route("LogsRoute", "/logs", page(LogsPage, { authRequired: true })),
    route("ShareRoute", "/share/:linkId", page(SharePage)),
    route("SignupRoute", "/signup", page(SignupPage)),
    route("LoginRoute", "/login", page(LoginPage)),

    query(getFolderContents, { entities: ["Folder", "File"] }),
    query(getAccessLogs, { entities: ["AccessLog", "File"] }),
    query(getShareLinkInfo, { entities: ["ShareLink", "File"], auth: false }),

    action(createFolder, { entities: ["Folder"] }),
    action(createShareLink, { entities: ["ShareLink", "File"] }),

    api("POST", "/api/upload", uploadFile, { entities: ["File", "Folder"], auth: true }),
    api("GET", "/api/download/:linkId", downloadFile, { entities: ["ShareLink", "File", "AccessLog"], auth: false }),
  ],
});

import { HttpError } from 'wasp/server';

const RUN_ID = "zrwuzpzyd7";

function suffixFolderName(name: string) {
  if (name.endsWith(`-${RUN_ID}`)) return name;
  return `${name}-${RUN_ID}`;
}

export const createFolder = async (args: { name: string; parentId?: number | null }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized');
  }
  if (!args.name) {
    throw new HttpError(400, 'Folder name is required');
  }

  const suffixedName = suffixFolderName(args.name);

  return context.entities.Folder.create({
    data: {
      name: suffixedName,
      parentId: args.parentId || null,
      userId: context.user.id,
    },
  });
};

export const createShareLink = async (
  args: { fileId: number; password?: string; expiresInMinutes?: number },
  context: any
) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized');
  }

  // Verify file belongs to user
  const file = await context.entities.File.findFirst({
    where: {
      id: args.fileId,
      userId: context.user.id,
    },
  });

  if (!file) {
    throw new HttpError(404, 'File not found');
  }

  let expiresAt: Date | null = null;
  if (args.expiresInMinutes) {
    expiresAt = new Date(Date.now() + args.expiresInMinutes * 60 * 1000);
  }

  return context.entities.ShareLink.create({
    data: {
      fileId: args.fileId,
      password: args.password || null,
      expiresAt,
    },
  });
};

import { HttpError } from 'wasp/server';

export const getFolderContents = async (args: { folderId?: number | null }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized');
  }

  const folderId = args.folderId ? Number(args.folderId) : null;

  let currentFolder = null;
  if (folderId) {
    currentFolder = await context.entities.Folder.findFirst({
      where: {
        id: folderId,
        userId: context.user.id,
      },
    });
    if (!currentFolder) {
      throw new HttpError(404, 'Folder not found');
    }
  }

  const subfolders = await context.entities.Folder.findMany({
    where: {
      parentId: folderId,
      userId: context.user.id,
    },
    orderBy: { name: 'asc' },
  });

  const files = await context.entities.File.findMany({
    where: {
      folderId: folderId,
      userId: context.user.id,
    },
    include: {
      shareLinks: true,
    },
    orderBy: { name: 'asc' },
  });

  // Construct breadcrumbs
  const path: any[] = [];
  let tempFolder = currentFolder;
  while (tempFolder) {
    path.unshift(tempFolder);
    if (tempFolder.parentId) {
      tempFolder = await context.entities.Folder.findFirst({
        where: {
          id: tempFolder.parentId,
          userId: context.user.id,
        },
      });
    } else {
      tempFolder = null;
    }
  }

  return {
    currentFolder,
    subfolders,
    files,
    path,
  };
};

export const getAccessLogs = async (args: any, context: any) => {
  if (!context.user) {
    throw new HttpError(401, 'Unauthorized');
  }

  return context.entities.AccessLog.findMany({
    where: {
      file: {
        userId: context.user.id,
      },
    },
    include: {
      file: true,
    },
    orderBy: {
      timestamp: 'desc',
    },
  });
};

export const getShareLinkInfo = async (args: { linkId: string }, context: any) => {
  if (!args.linkId) {
    throw new HttpError(400, 'Link ID is required');
  }

  const shareLink = await context.entities.ShareLink.findUnique({
    where: { id: args.linkId },
    include: {
      file: true,
    },
  });

  if (!shareLink) {
    throw new HttpError(404, 'Share link not found');
  }

  const isExpired = shareLink.expiresAt ? new Date() > new Date(shareLink.expiresAt) : false;

  return {
    id: shareLink.id,
    fileName: shareLink.file.name,
    fileSize: shareLink.file.size,
    isPasswordProtected: !!shareLink.password,
    isExpired,
  };
};

import multer from 'multer';
import fs from 'fs';
import path from 'path';

const uploadDir = '/home/user/app/uploads/';
if (!fs.existsSync(uploadDir)) {
  fs.mkdirSync(uploadDir, { recursive: true });
}

const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, uploadDir);
  },
  filename: (req, file, cb) => {
    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1e9);
    cb(null, uniqueSuffix + '-' + file.originalname);
  },
});

const upload = multer({ storage }).single('file');

export const uploadFile = (req: any, res: any, context: any) => {
  upload(req, res, async (err: any) => {
    if (err) {
      return res.status(500).json({ error: err.message });
    }
    if (!req.file) {
      return res.status(400).json({ error: 'No file uploaded' });
    }

    try {
      const folderId = req.body.folderId ? Number(req.body.folderId) : null;

      if (folderId) {
        const folder = await context.entities.Folder.findFirst({
          where: {
            id: folderId,
            userId: context.user.id,
          },
        });
        if (!folder) {
          return res.status(404).json({ error: 'Folder not found' });
        }
      }

      const fileRecord = await context.entities.File.create({
        data: {
          name: req.file.originalname,
          originalName: req.file.originalname,
          path: req.file.path,
          mimeType: req.file.mimetype,
          size: req.file.size,
          folderId: folderId,
          userId: context.user.id,
        },
      });

      return res.status(200).json(fileRecord);
    } catch (dbErr: any) {
      return res.status(500).json({ error: dbErr.message });
    }
  });
};

export const downloadFile = async (req: any, res: any, context: any) => {
  try {
    const { linkId } = req.params;
    const password = req.query.password;

    if (!linkId) {
      return res.status(400).json({ error: 'Link ID is required' });
    }

    const shareLink = await context.entities.ShareLink.findUnique({
      where: { id: linkId },
      include: {
        file: true,
      },
    });

    if (!shareLink) {
      return res.status(404).json({ error: 'Share link not found' });
    }

    // Check expiration
    if (shareLink.expiresAt && new Date() > new Date(shareLink.expiresAt)) {
      return res.status(410).json({ error: 'Share link has expired' });
    }

    // Check password
    if (shareLink.password && shareLink.password !== password) {
      return res.status(403).json({ error: 'Incorrect password' });
    }

    const filePath = shareLink.file.path;
    if (!fs.existsSync(filePath)) {
      return res.status(404).json({ error: 'File not found on server' });
    }

    // Log the access
    const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress || 'unknown';
    const userAgent = req.headers['user-agent'] || 'unknown';

    await context.entities.AccessLog.create({
      data: {
        fileId: shareLink.file.id,
        ip: Array.isArray(ip) ? ip[0] : ip,
        userAgent,
      },
    });

    // Serve file content
    res.setHeader('Content-Type', shareLink.file.mimeType);
    res.setHeader('Content-Disposition', `attachment; filename="${encodeURIComponent(shareLink.file.name)}"`);

    const fileStream = fs.createReadStream(filePath);
    fileStream.pipe(res);
  } catch (err: any) {
    return res.status(500).json({ error: err.message });
  }
};

import { useState } from "react";
import { signup } from "wasp/client/auth";
import { Link, useNavigate } from "react-router";

const RUN_ID = "zrwuzpzyd7";

function suffixUsername(username: string) {
  if (username.endsWith(`-${RUN_ID}`)) return username;
  return `${username}-${RUN_ID}`;
}

export function SignupPage() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    try {
      const suffixedUser = suffixUsername(username);
      await signup({ username: suffixedUser, password });
      navigate("/login");
    } catch (err: any) {
      setError(err.message || "An error occurred during signup");
    }
  };

  return (
    <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4 py-12 sm:px-6 lg:px-8">
      <div className="w-full max-w-md space-y-8 p-8 bg-white rounded-lg shadow" style={{ maxWidth: "400px", margin: "100px auto" }}>
        <div>
          <h2 className="mt-6 text-center text-3xl font-bold tracking-tight text-gray-900">
            Create your account
          </h2>
        </div>
