const RUN_ID = "zrwuzpzyd7";

function suffixUsername(username: string) {
  if (username.endsWith(`-${RUN_ID}`)) return username;
  return `${username}-${RUN_ID}`;
}

export function LoginPage() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    try {
      const suffixedUser = suffixUsername(username);
      try {
        // Try new signature login({ username, password })
        await login({ username: suffixedUser, password } as any);
      } catch (err: any) {
        // Fallback to old signature login(username, password)
        await (login as any)(suffixedUser, password);
      }
      navigate("/");
    } catch (err: any) {
      setError(err.message || "Invalid username or password");
